# shellcheck shell=bash
# run.sh から番号順に source される(前のファイルが作った状態は使わない)
# --- tb conv(振り分け・下書き・学習・段階)の使い方・誤りの文面・終了コード・JSON の形(期待値は消した bash 版の出力から作った。今はこれが約束)。
# 動きそのものは 12_conv.sh と 72_conv_learn.sh
_cc_saved=$(env | grep -E '^(TB_DB|HERDR_PANE_ID|FAKE_AGENTS|TB_CONV_[A-Z_]+)=' || true)
unset HERDR_PANE_ID TB_CONV_ROUTES TB_CONV_TEAMS
export TB_DB=$TMP/convcontract.db TB_CONV_DIR=$TMP/cc-conv TB_CONV_STATE_DIR=$TMP/cc-state
export TB_CONV_LEARN=$TMP/cc-learn.conf TB_CONV_STAGES=$TMP/cc-stages.conf TB_CONV_ROUTES=$TMP/cc-routes.conf
cp -R "$HERE/../../conversation" "$TB_CONV_DIR"
printf 'threshold = 2\ndeny = Acme\n' >"$TB_CONV_LEARN"
printf 'high = refusal\ndraft-save = available\nstage3 = thanks:teammate\nmin-pairs.1 = 1\nmin-samples.2 = 1\nmax-edit-ratio.2 = 0.95\nmin-adopted.2 = 1\nquiet-days.2 = 0\nquiet-days.3 = 0\n' >"$TB_CONV_STAGES"
CC=$TMP/cc-work; mkdir -p "$CC"
printf 'ありがとうございます。確認しました。\n' >"$CC/d"; printf '確認しました。ありがとう。\n' >"$CC/f"; : >"$CC/empty"
printf 'はい\n' >"$CC/short"
# 日時・組の ID・一時ディレクトリは毎回変わるので印に置き換える
ccmask() { sed -E "s|$TMP|TMP|g; s/pair-[0-9]{14}-[0-9a-f]{4}/pair-ID/g; s/[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:]{8}Z/TS/g; s/P-([a-z0-9-]{1,15})-[0-9a-f]{4}/P-\\1-XXXX/g"; }
ccerr() { local o r=0; o=$("$@" 2>&1) || r=$?; printf '%s\n' "$o" | ccmask; echo "rc=$r"; }

# ---- tb conv
eq "conv: no subcommand → usage on stdout, rc 2" "$(ccerr $TB conv)" $'tb conv route|routes-set|draft|voice|voice-check|length|kinds|patterns|lint ...   会話チームの振り分けと下書き(引数は tb help)\ntb conv pair-add|pairs|pair-show|candidate-add|ledger|candidate-adopt|candidate-reject|scan|learn-purge ...   会話の学習\ntb conv stage|stage-set|stage-reset|stage-log|incident|gate ...   会話チームの段階\n(古い名前 tb conv-<サブコマンド> も同じに使える)\nrc=2'
eq "conv help / unknown subcommand" "$(ccerr $TB conv help; ccerr $TB conv bogus)" $'tb conv route|routes-set|draft|voice|voice-check|length|kinds|patterns|lint ...   会話チームの振り分けと下書き(引数は tb help)\ntb conv pair-add|pairs|pair-show|candidate-add|ledger|candidate-adopt|candidate-reject|scan|learn-purge ...   会話の学習\ntb conv stage|stage-set|stage-reset|stage-log|incident|gate ...   会話チームの段階\n(古い名前 tb conv-<サブコマンド> も同じに使える)\nrc=0\ntb: conv: 不明なサブコマンド bogus(tb conv で一覧)\n(tb help で使い方)\nrc=2'

# ---- 振り分け
eq "conv route: bad args" "$(ccerr $TB conv route --text x; ccerr $TB conv route --event; ccerr $TB conv route --event a; ccerr $TB conv route --event A --counterpart b --depth c --severity d --deadline e)" $'tb: conv-route: 不明な引数 --text(依頼は --event --counterpart --depth --severity --deadline の 5 つの名前だけ。本文は渡さない)\n(tb help で使い方)\nrc=2\ntb: --event に値が必要です\n(tb help で使い方)\nrc=2\ntb: conv-route: --counterpart が要ります\n(tb help で使い方)\nrc=2\ntb: --event は英小文字で始まる 40 文字までの英小文字・数字・-: A\n(tb help で使い方)\nrc=2'
eq "conv route: no table (text / json)" "$(ccerr $TB conv route --event a --counterpart b --depth c --severity d --deadline e; ccerr $TB conv-route --event a --counterpart b --depth c --severity d --deadline e --json)" $'unregistered\treason=no-table\tneeds_human=yes\tversion=0\nrc=0\n{"status":"unregistered","kind":null,"counterpart":"b","channel":null,"timing":null,"severity":"d","needs_human":true,"reason":"no-table","table_version":0}\nrc=0'
eq "conv route --stdin: bad json" "$(echo 'x' | ccerr $TB conv route --stdin; echo '[1]' | ccerr $TB conv route --stdin; echo '{"event":"a","zz":"b","aa":1}' | ccerr $TB conv route --stdin; echo '{"event":1}' | ccerr $TB conv route --stdin; echo '{"event":"a"}' | ccerr $TB conv route --stdin)" $'tb: conv-route --stdin: JSON のオブジェクトを渡す\n(tb help で使い方)\nrc=2\ntb: conv-route --stdin: JSON のオブジェクトを渡す\n(tb help で使い方)\nrc=2\ntb: conv-route --stdin: 使えないキーがあります: zz aa (5 つの区分の名前だけ)\n(tb help で使い方)\nrc=2\ntb: conv-route --stdin: 値は文字列だけ\n(tb help で使い方)\nrc=2\ntb: conv-route: --counterpart が要ります\n(tb help で使い方)\nrc=2'
eq "conv routes-set: tty / looser / bad table" "$(ccerr $TB conv routes-set --bogus; printf 'x\n' | ccerr $TB conv routes-set; printf 'version = 1\n' | ccerr $TB conv routes-set --dry-run)" $'tb: conv-routes-set [--shared] [--approve-looser] [--dry-run] < 新しい表\n(tb help で使い方)\nrc=2\ntb: 振り分け表を書けません: L1: \'version = N\' / \'counterparts = ...\' / \'<5 欄> -> kind=... channel=... timing=...\' のどれでもありません\nrc=1\nversion 0 -> 1: 緩める(未登録 → 振り分け)=0 振り分け先の変更=0 厳しくする(振り分け → 未登録)=0\n(dry-run: 何も書いていません)\nrc=0'
printf 'version = 1\ncounterparts = teammate client\ninquiry teammate * low,normal * -> kind=thanks channel=same-thread timing=within-day\n' >"$TMP/cc-t1"
eq "conv routes-set: looser needs --approve-looser (20), then written" "$(ccerr $TB conv routes-set <"$TMP/cc-t1"; ccerr $TB conv routes-set --approve-looser <"$TMP/cc-t1")" $'version 0 -> 1: 緩める(未登録 → 振り分け)=2 振り分け先の変更=0 厳しくする(振り分け → 未登録)=0\ntb: 振り分けを緩める・変える変更です。人が内容を確かめたうえで --approve-looser を付けて実行してください\nrc=20\nversion 0 -> 1: 緩める(未登録 → 振り分け)=2 振り分け先の変更=0 厳しくする(振り分け → 未登録)=0\nconv-routes: file:TMP/cc-routes.conf(conv-routes-set:looser-approved)\nrc=0'
eq "conv routes-set: version must grow" "$(ccerr $TB conv routes-set --approve-looser <"$TMP/cc-t1")" $'tb: version を今の表(1)より大きくしてください(新しい表は 1)\nrc=1'
eq "conv route: routed (text / json) and unregistered" "$(ccerr $TB conv route --event inquiry --counterpart teammate --depth new --severity low --deadline none; ccerr $TB conv route --event inquiry --counterpart teammate --depth new --severity low --deadline none --json; ccerr $TB conv route --event inquiry --counterpart vendor --depth new --severity low --deadline none --json; echo '{"event":"inquiry","counterpart":"client","depth":"x","severity":"low","deadline":"y"}' | ccerr $TB conv route --stdin)" $'routed\tkind=thanks\tcounterpart=teammate\tchannel=same-thread\ttiming=within-day\tseverity=low\tversion=1\tline=3\nrc=0\n{"status":"routed","kind":"thanks","counterpart":"teammate","channel":"same-thread","timing":"within-day","severity":"low","needs_human":false,"table_version":1,"rule_line":3}\nrc=0\n{"status":"unregistered","kind":null,"counterpart":"vendor","channel":null,"timing":null,"severity":"low","needs_human":true,"reason":"counterpart","table_version":1}\nrc=0\nunregistered\treason=no-route\tneeds_human=yes\tversion=1\nrc=0'
$TB conv route --event inquiry --counterpart teammate --depth new --severity low --deadline none --json >"$CC/route.json"

# ---- 下書き
eq "conv draft: bad args" "$(ccerr $TB conv draft; ccerr $TB conv draft --kind a --route b; ccerr $TB conv draft --kind thanks --note '2 件'; ccerr $TB conv draft --kind thanks --ref 'a b'; ccerr $TB conv draft --kind thanks --max-chars 0; ccerr $TB conv draft --kind BAD; ccerr $TB conv draft --x)" $'tb: conv-draft: --route か --kind が要ります\n(tb help で使い方)\nrc=2\ntb: conv-draft: --route と --kind は一緒に使えません\n(tb help で使い方)\nrc=2\ntb: conv-draft: --note に数字があります(件数・番号・日付は書かず、一般化した言い方にする)\n(tb help で使い方)\nrc=2\ntb: conv-draft: --ref は 200 文字までで、空白・引用符・<> を含まない\n(tb help で使い方)\nrc=2\ntb: conv-draft: --max-chars は 1 以上の整数\n(tb help で使い方)\nrc=2\ntb: --kind は英小文字で始まる 40 文字までの英小文字・数字・-: BAD\n(tb help で使い方)\nrc=2\ntb: conv-draft (--route <tb conv-route --json の出力のファイル|-> | --kind <種別>) [--note 一般化した状況] [--ref 参照] [--max-chars N | --request <依頼のファイル>]\n(tb help で使い方)\nrc=2'
eq "conv draft --route: bad route json" "$(echo '{"status":"x"}' | ccerr $TB conv draft --route -; echo '{"status":"routed","kind":"BAD"}' | ccerr $TB conv draft --route -; ccerr $TB conv draft --route "$CC/none")" $'tb: conv-draft --route: tb conv-route --json の出力を渡す\n(tb help で使い方)\nrc=2\ntb: conv-draft --route: kind の値が不正です\n(tb help で使い方)\nrc=2\ntb: --route のファイルを読めません: TMP/cc-work/none\n(tb help で使い方)\nrc=2'
eq "conv draft --route: routed (head and request part)" "$($TB conv draft --route "$CC/route.json" --note '急ぎではない' --ref T-x-001 --request "$CC/d" | sed -n '1,2p;/^## 今回の依頼/,$p')" $'# 下書きの指示(tb conv-draft)\nチーム: thanks\n## 今回の依頼\n\n- 種別: thanks\n- 相手の区分: teammate / 経路の区分: same-thread / 時機: within-day / 重大度: low\n- 状況(一般化したもの): 急ぎではない\n- 参照: T-x-001(元の文面は参照先で読む。ここには写さない)\n- 長さ: 18 文字以内(依頼より長くしない)'
eq "conv draft --route: unregistered with reason" "$(echo '{"status":"unregistered","reason":{"a":1},"counterpart":"vendor","severity":5}' | $TB conv draft --route - | sed -n '1,3p;/^## 今回の依頼/,$p')" $'# 下書きの指示(tb conv-draft)\nチーム: なし。共通の土台だけで下書きします — 振り分け表に無い依頼です({\n  "a": 1\n## 今回の依頼\n\n- 種別: -\n- 相手の区分: vendor / 経路の区分: - / 時機: - / 重大度: -\n- 状況(一般化したもの): -\n- 参照: -(元の文面は参照先で読む。ここには写さない)\n- 長さ: 依頼より長くしない'
eq "conv draft --kind: no team" "$(TB_CONV_TEAMS=off $TB conv draft --kind thanks | head -1; $TB conv draft --kind nope | head -1)" $'# 下書きの指示(tb conv-draft)\n# 下書きの指示(tb conv-draft)'

# ---- 声の役・長さ
eq "conv voice: bad args" "$(ccerr $TB conv voice; ccerr $TB conv voice nope --draft "$CC/d"; ccerr $TB conv voice direct; ccerr $TB conv voice brevity --draft "$CC/d"; ccerr $TB conv voice direct --request-chars x; ccerr $TB conv voice direct --bogus)" $'tb: conv-voice <役> --draft <下書きのファイル> [--request <依頼のファイル> | --request-chars N]\n(tb help で使い方)\nrc=2\ntb: conv-voice: 声の役がありません: nope(あるのは: brevity direct empathetic receiver )\n(tb help で使い方)\nrc=2\ntb: conv-voice: --draft が要ります\n(tb help で使い方)\nrc=2\ntb: conv-voice brevity: --request か --request-chars が要ります(依頼より長いかを必ず言うため)\n(tb help で使い方)\nrc=2\ntb: --request-chars は整数\n(tb help で使い方)\nrc=2\ntb: conv-voice: 不明な引数 --bogus\n(tb help で使い方)\nrc=2'
eq "conv voice brevity: tail" "$($TB conv voice brevity --draft "$CC/d" --request "$CC/short" | sed -n '/^## 出力の形/,$p')" $'## 出力の形\n\n- 1 行 1 点、行頭は「- 」。多くても 3 点。直す点が無ければ「- なし」\n- 1 行目に必ず「長さ: 依頼より長い」と書く(下書き 18 文字 / 依頼 2 文字)\n- 下書きを書き直さない。ほかの役の意見は見ていない前提で、自分の観点だけを書く\n\n## 下書き\n\nありがとうございます。確認しました。'
eq "conv voice-check: shapes" "$(printf -- '- a\n・b\n' | ccerr $TB conv voice-check direct; printf 'x\n' | ccerr $TB conv voice-check direct; printf '\n' | ccerr $TB conv voice-check direct; printf -- '- a\n- b\n- c\n- d\n' | ccerr $TB conv voice-check direct; printf -- '- a\n' | ccerr $TB conv voice-check brevity; printf -- '長さ: 依頼より長くない\n- a\n' | ccerr $TB conv voice-check brevity --draft "$CC/d" --request "$CC/short"; printf -- '長さ：依頼より長い\n- a\n' | ccerr $TB conv voice-check brevity --draft "$CC/d" --request "$CC/short"; ccerr $TB conv voice-check direct --draft "$CC/d" </dev/null)" $'- a\n- b\nrc=0\ntb: 行頭が「- 」ではない行があります\nrc=1\ntb: 点がありません(直す点が無ければ「- なし」)\nrc=1\ntb: 点が多すぎます(4 点。多くても 3 点)\nrc=1\ntb: brevity は 1 行目に「長さ: 依頼より長い」か「長さ: 依頼より長くない」を書きます\nrc=1\ntb: 長さの判定が実際と違います(実際は「依頼より長い」)\nrc=1\n長さ: 依頼より長い\n- a\nrc=0\ntb: conv-voice-check: --draft と --request は両方を渡す\n(tb help で使い方)\nrc=2'
eq "conv length" "$(ccerr $TB conv length --draft "$CC/d" --request "$CC/short"; ccerr $TB conv length --draft "$CC/short" --request "$CC/d"; ccerr $TB conv length --draft x)" $'draft=18\trequest=2\tlonger=yes\nrc=1\ndraft=2\trequest=18\tlonger=no\nrc=0\ntb: conv-length --draft <下書き> --request <依頼>\n(tb help で使い方)\nrc=2'
eq "conv kinds / patterns / lint" "$($TB conv kinds --json | jq -c 'map(.kind)'; ccerr $TB conv kinds x; ccerr $TB conv patterns; ccerr $TB conv patterns nope; ccerr $TB conv lint x; ccerr $TB conv lint)" $'["inquiry-answer","refusal","reminder","review-reply","thanks"]\ntb: conv-kinds [--json]\n(tb help で使い方)\nrc=2\ntb: conv-patterns <種別> [--all]\n(tb help で使い方)\nrc=2\ntb: 種別がありません: nope\nrc=1\ntb: conv-lint\n(tb help で使い方)\nrc=2\nconv-routes: version 1、1 行(file:TMP/cc-routes.conf)\nok\nrc=0'

# ---- 学習
eq "conv pair-add: bad args" "$(ccerr $TB conv pair-add; ccerr $TB conv pair-add --kind nope --draft-file x --final-file y; ccerr $TB conv pair-add --kind thanks --draft-file x --final-file y; ccerr $TB conv pair-add --kind thanks --draft-file x --final-file y --posted --situation ' ' --intent i; ccerr $TB conv pair-add --kind thanks --draft-file "$CC/none" --final-file y --posted --situation s --intent i; ccerr $TB conv pair-add --kind thanks --draft-file "$CC/d" --final-file "$CC/empty" --posted --situation s --intent i; ccerr $TB conv pair-add --kind thanks --draft-file "$CC/d" --final-file "$CC/f" --posted --situation s --intent i --points-offered 1 --points-accepted 2; ccerr $TB conv pair-add --bogus)" $'tb: conv-pair-add --kind K --draft-file F --final-file F --situation S --intent I --posted\n(tb help で使い方)\nrc=2\ntb: 未登録の種別です(conversation/kinds/nope がありません): nope\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: 人が送ったあとにだけ記録します(--posted を付ける)\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: --situation と --intent(一般化した状況と意図)が要ります\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: 下書きのファイルを読めません: TMP/cc-work/none\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: 送った文のファイルが無いか空です: TMP/cc-work/empty\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: --points-offered と --points-accepted は 0 以上の整数で、受け入れた数 <= 示された数\n(tb help で使い方)\nrc=2\ntb: conv-pair-add: 不明な引数 --bogus\n(tb help で使い方)\nrc=2'
eq "conv pair-add: from an agent pane" "$(FAKE_AGENTS='[{"pane_id":"wW:p1","name":"worker1"}]' HERDR_PANE_ID=wW:p1 ccerr $TB conv pair-add --kind thanks --draft-file "$CC/d" --final-file "$CC/f" --posted --situation s --intent i)" $'tb: tb conv-pair-add は人が自分の端末で実行します(agent \'worker1\' の pane からは実行できません)。記録 Q-1(例外は人が tb approval approve Q-1 で許可できます)\nrc=1'
p1=$($TB conv pair-add --kind thanks --draft-file "$CC/d" --final-file "$CC/f" --posted --situation '状況 Acme から 2026-11-19 に' --intent '受け取りを伝える' --points-offered 3 --points-accepted 2 | cut -f1)
sleep 1   # 記録の日時(秒)で並ぶので、同じ秒にしない
p2=$($TB conv pair-add --kind thanks --draft-file "$CC/empty" --final-file "$CC/f" --posted --situation '別の状況' --intent 'お礼' | cut -f1)
eq "conv pair-add: meta.json" "$(ccmask <"$TB_CONV_STATE_DIR/pairs/thanks/$p1/meta.json"; ccmask <"$TB_CONV_STATE_DIR/pairs/thanks/$p2/meta.json")" $'{\n  "id": "pair-ID",\n  "kind": "thanks",\n  "situation": "状況 <name> から 2026-11 に",\n  "intent": "受け取りを伝える",\n  "recorded_at": "TS",\n  "posted_by": "human",\n  "edit_ratio": 0.889,\n  "draft_chars": 18,\n  "final_chars": 13,\n  "human_written": false,\n  "points_offered": 3,\n  "points_accepted": 2\n}\n{\n  "id": "pair-ID",\n  "kind": "thanks",\n  "situation": "別の状況",\n  "intent": "お礼",\n  "recorded_at": "TS",\n  "posted_by": "human",\n  "edit_ratio": 1.000,\n  "draft_chars": 0,\n  "final_chars": 13,\n  "human_written": true,\n  "points_offered": null,\n  "points_accepted": null\n}'
eq "conv pairs (text / json)" "$($TB conv pairs | ccmask; $TB conv pairs --kind thanks --json | ccmask; ccerr $TB conv pairs --kind nope; ccerr $TB conv pairs --x)" $'pair-ID\tthanks\tTS\t0.889\t状況 <name> から 2026-11 に\npair-ID\tthanks\tTS\t1.000\t別の状況\n[\n  {\n    "id": "pair-ID",\n    "kind": "thanks",\n    "situation": "状況 <name> から 2026-11 に",\n    "intent": "受け取りを伝える",\n    "recorded_at": "TS",\n    "posted_by": "human",\n    "edit_ratio": 0.889,\n    "draft_chars": 18,\n    "final_chars": 13,\n    "human_written": false,\n    "points_offered": 3,\n    "points_accepted": 2\n  },\n  {\n    "id": "pair-ID",\n    "kind": "thanks",\n    "situation": "別の状況",\n    "intent": "お礼",\n    "recorded_at": "TS",\n    "posted_by": "human",\n    "edit_ratio": 1.000,\n    "draft_chars": 0,\n    "final_chars": 13,\n    "human_written": true,\n    "points_offered": null,\n    "points_accepted": null\n  }\n]\ntb: 未登録の種別です(conversation/kinds/nope がありません): nope\n(tb help で使い方)\nrc=2\ntb: conv-pairs [--kind K] [--json]\n(tb help で使い方)\nrc=2'
eq "conv pair-show" "$($TB conv pair-show "$p2" | ccmask; ccerr $TB conv pair-show bad; ccerr $TB conv pair-show pair-20260101000000-abcd; ccerr $TB conv pair-show)" $'{\n  "id": "pair-ID",\n  "kind": "thanks",\n  "situation": "別の状況",\n  "intent": "お礼",\n  "recorded_at": "TS",\n  "posted_by": "human",\n  "edit_ratio": 1.000,\n  "draft_chars": 0,\n  "final_chars": 13,\n  "human_written": true,\n  "points_offered": null,\n  "points_accepted": null\n}\n--- 下書き\n\n--- 送った文\n確認しました。ありがとう。\n\ntb: 組の ID は pair-<日時 14 桁>-<16 進 4 桁>: bad\n(tb help で使い方)\ntb: 組が見つかりません: bad\nrc=1\ntb: 組が見つかりません: pair-ID\nrc=1\ntb: conv-pair-show <pair-id>\n(tb help で使い方)\nrc=2'
eq "conv candidate-add: bad args" "$(ccerr $TB conv candidate-add; ccerr $TB conv candidate-add --kind thanks --direction X --desc d --evidence human-edit; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence nope; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence human-edit --conclusion mid; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence human-edit; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence human-edit --pair bad; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence human-written --pair "$p1"; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence human-edit --pair "$p2"; ccerr $TB conv candidate-add --kind thanks --direction ab --desc d --evidence other-source)" $'tb: conv-candidate-add --kind K --direction D --desc 説明 --evidence E (--pair ID | --ref 説明)\n(tb help で使い方)\nrc=2\ntb: --direction は変更の向きの短い名前(英小文字・数字・-、例 conclusion-first): X\n(tb help で使い方)\nrc=2\ntb: --evidence は human-edit human-written other-source agent-generated のどれか: nope\n(tb help で使い方)\nrc=2\ntb: --conclusion は first か last: mid\n(tb help で使い方)\nrc=2\ntb: conv-candidate-add: --evidence human-edit には --pair(人が送った組)が要ります\n(tb help で使い方)\nrc=2\ntb: 組の ID は pair-<日時 14 桁>-<16 進 4 桁>: bad\n(tb help で使い方)\ntb: 組が見つかりません: bad\nrc=1\ntb: 組 pair-ID は下書きを元にしています(human-written は人が一から書いた組だけ)\nrc=1\ntb: 組 pair-ID には人の手直しがありません(下書きのまま、または一から書いたもの。一から書いたものは human-written)\nrc=1\ntb: conv-candidate-add: --evidence other-source には --ref(出どころの一般化した説明)が要ります\n(tb help で使い方)\nrc=2'
eq "conv candidate-add: records, dedupes, proposes" "$(ccerr $TB conv candidate-add --kind thanks --direction short-thanks --desc '結論を先に Acme' --evidence human-edit --pair "$p1" --situation 'お礼の場面' --intent '短く伝える' --conclusion first; ccerr $TB conv candidate-add --kind thanks --direction short-thanks --desc d --evidence human-edit --pair "$p1"; ccerr $TB conv candidate-add --kind thanks --direction short-thanks --desc d --evidence agent-generated; ccerr $TB conv candidate-add --kind thanks --direction short-thanks --desc d --evidence other-source --ref '別の本 12 章' --permissive)" $'short-thanks\tcandidate\t1/2\nrc=0\n同じ証拠は記録済みです(short-thanks pair-ID)\nshort-thanks\tcandidate\t1/2\nrc=0\nshort-thanks\tcandidate\t1/2\nrc=0\nshort-thanks\tproposed\t2/2\nrc=0'
eq "conv ledger (text / json)" "$($TB conv ledger; $TB conv ledger --kind thanks --json | ccmask; ccerr $TB conv ledger --x)" $'thanks\tshort-thanks\tproposed\t2/2\t1\t0\t1\t1\tpermissive\t結論を先に <name>\n[\n  {\n    "kind": "thanks",\n    "direction": "short-thanks",\n    "state": "proposed",\n    "permissive": true,\n    "counted": 2,\n    "threshold": 2,\n    "evidence": {\n      "human-edit": 1,\n      "human-written": 0,\n      "other-source": 1,\n      "agent-generated": 1\n    },\n    "situation": "お礼の場面",\n    "intent": "短く伝える",\n    "ending": "",\n    "conclusion": "first",\n    "avoid": "",\n    "desc": "結論を先に <name>",\n    "updated_at": "TS",\n    "pattern_id": null\n  }\n]\ntb: conv-ledger [--kind K] [--json]\n(tb help で使い方)\nrc=2'
eq "conv candidate-adopt: refusals" "$(ccerr $TB conv candidate-adopt; ccerr $TB conv candidate-adopt thanks nope; ccerr $TB conv candidate-adopt thanks short-thanks; ccerr $TB conv candidate-adopt thanks short-thanks --approve-permissive --situation '<n> 件'; ccerr $TB conv candidate-adopt thanks short-thanks --approve-permissive --intent 'Bob に伝える'; ccerr $TB conv candidate-adopt thanks short-thanks --bogus)" $'tb: conv-candidate-adopt <kind> <direction> [--approve-permissive] [--situation S --intent I --ending E --conclusion first|last --avoid A]\n(tb help で使い方)\nrc=2\ntb: 候補がありません: thanks nope\nrc=1\ntb: 許す方向の変更です。採用するなら --approve-permissive を付けて明示してください\nrc=1\ntb: 置き換えた印(<name> <n> など)が残っています。一般化した言い方に直して --situation などで渡してください: <n> 件 | 短く伝える |  | \nrc=1\ntb: 置き換えた印(<name> <n> など)が残っています。一般化した言い方に直して --situation などで渡してください: お礼の場面 | <name> に伝える |  | \nrc=1\ntb: conv-candidate-adopt: 不明な引数 --bogus\n(tb help で使い方)\nrc=2'
eq "conv candidate-adopt: adopts" "$(ccerr $TB conv candidate-adopt thanks short-thanks --approve-permissive | ccmask; tail -1 "$TB_CONV_DIR/kinds/thanks/patterns.conf"; ccerr $TB conv candidate-adopt thanks short-thanks)" $'P-short-thanks adopted → TMP/cc-conv/kinds/thanks/patterns.conf\nrc=0\nP-short-thanks | adopted | human-edit | お礼の場面 | 短く伝える | - | first | -\ntb: 採用済みです: thanks short-thanks\nrc=1'
eq "conv candidate-reject" "$(ccerr $TB conv candidate-reject; ccerr $TB conv candidate-reject thanks nope; ccerr $TB conv candidate-reject thanks short-thanks; $TB conv candidate-add --kind reminder --direction rx --desc d --evidence other-source --ref r >/dev/null; ccerr $TB conv candidate-reject reminder rx; $TB conv ledger --kind reminder | cut -f3)" $'tb: conv-candidate-reject <kind> <direction>\n(tb help で使い方)\nrc=2\ntb: 候補がありません: thanks nope\nrc=1\ntb: 採用済みです。外すときは patterns.conf の行を人が消してください\nrc=1\nrx rejected\nrc=0\nrejected'
eq "conv scan" "$(echo 'see https://x.example and Acme' | ccerr $TB conv scan; echo 'ふつうの文' | ccerr $TB conv scan; ccerr $TB conv scan x)" $'url\thttps://x.example\nname\tAcme\ndeny\tAcme\nrc=1\n\nrc=0\ntb: conv-scan < 文\n(tb help で使い方)\nrc=2'

# ---- 段階
eq "conv stage (text / json)" "$($TB conv stage thanks; $TB conv stage refusal --json; ccerr $TB conv stage --x; ccerr $TB conv stage nope)" $'thanks\tstage 0/3\tpairs 2\tedit 0.945\tadopted 1\tquiet 0d\tnext ok\n[\n  {\n    "kind": "refusal",\n    "max_stage": 1,\n    "stage": 0,\n    "pairs": 0,\n    "window_days": 28,\n    "window_samples": 0,\n    "window_edit_ratio": null,\n    "role_points_offered": 0,\n    "role_points_accepted": 0,\n    "adopted_patterns": 0,\n    "last_incident": null,\n    "quiet_days": 0,\n    "days_at_stage": null,\n    "role_acceptance": null,\n    "next": {\n      "ok": false,\n      "unmet": [\n        "記録した組が 0 件(min-pairs.1 = 1)"\n      ]\n    }\n  }\n]\ntb: conv-stage [<kind>] [--json]\n(tb help で使い方)\nrc=2\ntb: 未登録の種別です(conversation/kinds/nope がありません): nope\n(tb help で使い方)\nrc=2'
eq "conv stage-set: refusals" "$(ccerr $TB conv stage-set; ccerr $TB conv stage-set thanks 5 --reason r; ccerr $TB conv stage-set thanks 1; ccerr $TB conv stage-set thanks 2 --reason r; ccerr $TB conv stage-set thanks 0 --reason r; ccerr $TB conv stage-set refusal 1 --reason r --x)" $'tb: conv-stage-set <kind> <0-3> --reason R [--override]\n(tb help で使い方)\nrc=2\ntb: 段階は 0〜3: 5\n(tb help で使い方)\nrc=2\ntb: conv-stage-set: --reason(人が決めた理由)が要ります\n(tb help で使い方)\nrc=2\ntb: 上げるのは 1 段ずつです(今 0)\nrc=1\nthanks は既に段階 0 です\nrc=0\ntb: conv-stage-set: 不明な引数 --x\n(tb help で使い方)\nrc=2'
eq "conv stage-set: raise to 3 step by step, high stops at 1" "$(ccerr $TB conv stage-set thanks 1 --reason r; ccerr $TB conv stage-set thanks 2 --reason r; ccerr $TB conv stage-set thanks 3 --reason r; ccerr $TB conv stage-set refusal 1 --reason r --override; ccerr $TB conv stage-set refusal 2 --reason r --override; ccerr $TB conv stage-set reminder 1 --reason r)" $'thanks: 段階 0 → 1 (raise)\nrc=0\nthanks: 段階 1 → 2 (raise)\nrc=0\nthanks: 段階 2 → 3 (raise)\nrc=0\nrefusal: 段階 0 → 1 (override)\nrc=0\ntb: refusal は high(問題の指摘・断り・組織の外)の種別なので、段階 1 より上にしません(conv-stages の high =)\nrc=4\ntb: 段階 1 に上げる条件を満たしていません(人が判断して上げるなら --override):\n記録した組が 0 件(min-pairs.1 = 1)\nrc=4'
eq "conv stage-log (text / json)" "$($TB conv stage-log thanks | ccmask; $TB conv stage-log refusal --json | ccmask; ccerr $TB conv stage-log --x)" $'TS\tthanks\t0→1\traise\thuman\tr\nTS\tthanks\t1→2\traise\thuman\tr\nTS\tthanks\t2→3\traise\thuman\tr\n[\n  {\n    "at": "TS",\n    "kind": "refusal",\n    "from": 0,\n    "to": 1,\n    "how": "override",\n    "by": "human",\n    "reason": "r",\n    "metrics": {\n      "stage": 0,\n      "pairs": 0,\n      "window_days": 28,\n      "window_samples": 0,\n      "window_edit_ratio": null,\n      "role_points_offered": 0,\n      "role_points_accepted": 0,\n      "adopted_patterns": 0,\n      "last_incident": null,\n      "quiet_days": 0,\n      "days_at_stage": null,\n      "role_acceptance": null\n    }\n  }\n]\ntb: conv-stage-log [<kind>] [--json]\n(tb help で使い方)\nrc=2'
eq "conv gate" "$(ccerr $TB conv gate thanks --action post --counterpart teammate --source-vis team --dest-vis team; ccerr $TB conv gate thanks --action post --counterpart client --source-vis team --dest-vis team; ccerr $TB conv gate thanks --action save-draft --source-vis team --dest-vis org; ccerr $TB conv gate thanks --action save-draft --severity high; ccerr $TB conv gate refusal --action review --dest-vis external; ccerr $TB conv gate reminder --action review; ccerr $TB conv gate thanks --action draft; ccerr $TB conv gate thanks --action x; ccerr $TB conv gate thanks --action draft --severity x; ccerr $TB conv gate thanks --action draft --counterpart X; ccerr $TB conv gate thanks --action draft --source-vis x; ccerr $TB conv gate)" $'ask\nreason: 段階 3: この 1 通を人が承認すれば送れます(承認なしには送らない)\nstage: 3 (設定 3, 上限 3)\nrc=20\ndeny\nreason: stage3 = の一覧に thanks:client がありません。送るのは人です\nstage: 3 (設定 3, 上限 3)\nrc=4\ndeny\nreason: 元の情報(team)より広い範囲(org)へ出すことになります\nstage: 3 (設定 3, 上限 3)\nrc=4\ndeny\nreason: 下書き保存は段階 2 以上の種別だけ\nstage: 1 (設定 3, 上限 1, severity high)\nrc=4\nallow\nreason: 声の役割の指摘(段階 1 以上)\nstage: 1 (設定 1, 上限 1, 組織の外へ出る)\nrc=0\ndeny\nreason: 段階 0 では声の役割を使いません\nstage: 0 (設定 0, 上限 3)\nrc=4\nallow\nreason: 下書きはどの段階でも作れます(送るのは人)\nstage: 3 (設定 3, 上限 3)\nrc=0\ntb: conv-gate: --action は draft|review|save-draft|post\n(tb help で使い方)\nrc=2\ntb: conv-gate: --severity は low|normal|high\n(tb help で使い方)\nrc=2\ntb: conv-gate: --counterpart は相手の区分の名前(英小文字・数字・-)\n(tb help で使い方)\nrc=2\ntb: conv-gate: --source-vis は private team org external のどれか\n(tb help で使い方)\nrc=2\ntb: conv-gate <kind> --action draft|review|save-draft|post [--counterpart C] [--severity S] [--source-vis V --dest-vis V]\n(tb help で使い方)\nrc=2'
eq "conv incident" "$(ccerr $TB conv incident; ccerr $TB conv incident thanks; ccerr $TB conv incident thanks --note '誤って保存 Acme' | ccmask; tail -1 "$TB_CONV_STATE_DIR/incidents.tsv" | ccmask)" $'tb: conv-incident <kind> --note N\n(tb help で使い方)\nrc=2\ntb: conv-incident: --note が要ります\n(tb help で使い方)\nrc=2\nthanks: 事故を記録しました(段階は 3 のまま。下げるなら tb conv-stage-set thanks 1 --reason ...)\nrc=0\nTS\tthanks\t誤って保存 <name>'
eq "conv stage-reset" "$(ccerr $TB conv stage-reset; ccerr $TB conv stage-reset --to 2 --reason r; ccerr $TB conv stage-reset --reason r; ccerr $TB conv stage-reset --to 0 --reason r; ccerr $TB conv stage-reset --to 0 --reason r)" $'tb: conv-stage-reset: --reason が要ります\n(tb help で使い方)\nrc=2\ntb: conv-stage-reset: --to は 0 か 1\n(tb help で使い方)\nrc=2\nthanks: 段階 3 → 1\nrc=0\nrefusal: 段階 1 → 0\nthanks: 段階 1 → 0\nrc=0\n段階 0 より上の種別はありません\nrc=0'
eq "conv learn-purge" "$(ccerr $TB conv learn-purge; ccerr $TB conv learn-purge --kind BAD --yes; ccerr $TB conv learn-purge --kind thanks --yes; ls "$TB_CONV_STATE_DIR/pairs" "$TB_CONV_STATE_DIR/ledger" | ccmask; ccerr $TB conv learn-purge --yes; ls "$TB_CONV_STATE_DIR")" $'tb: conv-learn-purge: 組と台帳を消します。よければ --yes を付ける\n(tb help で使い方)\nrc=2\ntb: 種別の名前が不正です: BAD\n(tb help で使い方)\nrc=2\n消しました: thanks(採用済みのパターンと段階の記録は残っています)\nrc=0\nTMP/cc-state/ledger:\nreminder.evidence.tsv\nreminder.tsv\n\nTMP/cc-state/pairs:\n消しました: 全種別(採用済みのパターンと段階の記録は残っています)\nrc=0\nincidents.tsv\nstage-log.tsv'
eq "conv: old names still work" "$(ccerr $TB conv-kinds x; ccerr $TB conv-stage-log --x; ccerr $TB conv-gate)" $'tb: conv-kinds [--json]\n(tb help で使い方)\nrc=2\ntb: conv-stage-log [<kind>] [--json]\n(tb help で使い方)\nrc=2\ntb: conv-gate <kind> --action draft|review|save-draft|post [--counterpart C] [--severity S] [--source-vis V --dest-vis V]\n(tb help で使い方)\nrc=2'

